diff --git a/repro/inline-assertion/check.cjs b/repro/inline-assertion/check.cjs
new file mode 100644
index 000000000..0b444aac3
--- /dev/null
+++ b/repro/inline-assertion/check.cjs
@@ -0,0 +1,51 @@
+// Asserts the expected behavior from the report: hovering `Test` in input.ts
+// (the report's code, verbatim) shows `{ prop1: "hello"; }`, not
+// `{ prop1: Wrapper<"hello">; }`.
+//
+// Usage (from the repo root):  node repro/inline-assertion/check.cjs
+// Optional: TS_PATH=/path/to/typescript.js to test another compiler build.
+const path = require("path");
+const fs = require("fs");
+
+const tsPath = path.resolve(process.env.TS_PATH || "built/local/typescript.js");
+const ts = require(tsPath);
+const fileName = path.resolve(__dirname, "input.ts");
+const text = fs.readFileSync(fileName, "utf8");
+
+const host = {
+    getScriptFileNames: () => [fileName],
+    getScriptVersion: () => "1",
+    getScriptSnapshot: f => {
+        const content = f === fileName ? text : ts.sys.readFile(f);
+        return content === undefined ? undefined : ts.ScriptSnapshot.fromString(content);
+    },
+    getCurrentDirectory: () => __dirname,
+    getCompilationSettings: () => ({ strict: true, target: ts.ScriptTarget.ESNext, types: [], noEmit: true }),
+    getDefaultLibFileName: o => ts.getDefaultLibFilePath(o),
+    fileExists: f => f === fileName || ts.sys.fileExists(f),
+    readFile: f => f === fileName ? text : ts.sys.readFile(f),
+};
+const service = ts.createLanguageService(host, ts.createDocumentRegistry());
+
+// Guard against a broken setup (e.g. missing lib files), which changes what Test is.
+const setupErrors = service.getSemanticDiagnostics(fileName).concat(service.getSyntacticDiagnostics(fileName));
+if (setupErrors.length) {
+    console.error("SETUP ERROR: input.ts has diagnostics:");
+    for (const d of setupErrors) console.error("  " + ts.flattenDiagnosticMessageText(d.messageText, "\n"));
+    process.exit(2);
+}
+
+const marker = "type Test = ";
+const pos = text.indexOf(marker) + "type ".length;
+const info = service.getQuickInfoAtPosition(fileName, pos);
+const actual = ts.displayPartsToString(info.displayParts).replace(/\s+/g, " ").trim();
+const expected = 'type Test = { prop1: "hello"; }';
+
+console.log(`typescript ${ts.version} (${tsPath})`);
+console.log(`expected: ${expected}`);
+console.log(`actual:   ${actual}`);
+if (actual !== expected) {
+    console.error("FAIL: Test is not displayed as { prop1: \"hello\"; }");
+    process.exit(1);
+}
+console.log("PASS");
diff --git a/repro/inline-assertion/input.ts b/repro/inline-assertion/input.ts
new file mode 100644
index 000000000..7c28a519a
--- /dev/null
+++ b/repro/inline-assertion/input.ts
@@ -0,0 +1,21 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
